const fs = require('fs');
const raw = $input.first().json.choices[0].message.content;
const data = JSON.parse(raw);

// sanitize body: 去掉以 # 开头的行 (裸 tag) 和多余空行
let body = (data.body || '').split('\n')
  .filter(line => !/^\s*#+\s*[\u4e00-\u9fa5]/.test(line))
  .join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// dedupe + normalize tags (去 ##, 补 #, 去重)
const tagsClean = [...new Set((data.tags || []).map(t => t.replace(/^#+/, '').trim()).filter(Boolean))];

const ts = new Date().toISOString().replace(/[-:T]/g,'').substring(0,15);
const draftDir = `/home/david/xhs-drafts/${ts}`;
fs.mkdirSync(draftDir, { recursive: true });
const mdPath = `${draftDir}/note.md`;
const md = `# ${data.title}\n\n${body}\n\n${tagsClean.map(t=>'#'+t).join(' ')}\n`;
fs.writeFileSync(mdPath, md);

const prompts = data.image_prompts || [];
const result = [];
for (let i = 0; i < Math.min(9, prompts.length); i++) {
  result.push({ json: {
    prompt: prompts[i],
    index: i + 1,
    draft_dir: draftDir,
    md_path: mdPath,
    title: data.title,
    total: Math.min(9, prompts.length)
  }});
}
return result;

const item = $input.first().json;
const seed = Math.floor(Math.random() * 1000000000);
const workflow = {
  '1': {class_type:'UNETLoader', inputs:{unet_name:'qwen_image_fp8_e4m3fn.safetensors', weight_dtype:'default'}},
  '2': {class_type:'CLIPLoader', inputs:{clip_name:'qwen_2.5_vl_7b_fp8_scaled.safetensors', type:'qwen_image'}},
  '3': {class_type:'VAELoader', inputs:{vae_name:'qwen_image_vae.safetensors'}},
  '4': {class_type:'ModelSamplingAuraFlow', inputs:{model:['1',0], shift:3.1}},
  '5': {class_type:'CLIPTextEncode', inputs:{clip:['2',0], text:item.prompt}},
  '6': {class_type:'CLIPTextEncode', inputs:{clip:['2',0], text:''}},
  '7': {class_type:'EmptySD3LatentImage', inputs:{width:1024, height:1024, batch_size:1}},
  '8': {class_type:'KSampler', inputs:{model:['4',0], positive:['5',0], negative:['6',0], latent_image:['7',0], seed, steps:20, cfg:2.5, sampler_name:'euler', scheduler:'simple', denoise:1.0}},
  '9': {class_type:'VAEDecode', inputs:{samples:['8',0], vae:['3',0]}},
  '10': {class_type:'SaveImage', inputs:{images:['9',0], filename_prefix:`n8n-xhs-${item.index}`}}
};
return [{ json: {
  comfy_body: { prompt: workflow, client_id: 'n8n' },
  index: item.index,
  draft_dir: item.draft_dir,
  md_path: item.md_path,
  title: item.title
}}];

const fs = require('fs');
const http = require('http');

const promptId = $input.first().json.prompt_id;
const prev = $('Build Comfy Workflow').item.json;
const draftDir = prev.draft_dir;
const index = prev.index;

async function getJson(url) {
  return new Promise((resolve, reject) => {
    http.get(url, res => {
      let d = ''; res.on('data', c => d += c);
      res.on('end', () => resolve(JSON.parse(d)));
    }).on('error', reject);
  });
}
async function getBinary(url) {
  return new Promise((resolve, reject) => {
    http.get(url, res => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => resolve(Buffer.concat(chunks)));
    }).on('error', reject);
  });
}

const deadline = Date.now() + 900000;
let result = null;
while (Date.now() < deadline) {
  const d = await getJson(`http://127.0.0.1:8189/history/${promptId}`);
  if (d[promptId]) {
    const entry = d[promptId];
    const st = entry.status || {};
    if (st.completed) {
      const outputs = entry.outputs || {};
      for (const nodeId in outputs) {
        for (const img of (outputs[nodeId].images || [])) {
          const url = `http://127.0.0.1:8189/view?filename=${img.filename}&subfolder=${img.subfolder||''}&type=output`;
          const buf = await getBinary(url);
          const dest = `${draftDir}/img-${String(index).padStart(2,'0')}-${img.filename}`;
          fs.writeFileSync(dest, buf);
          result = { saved: dest, size: buf.length };
          break;
        }
        if (result) break;
      }
      break;
    }
    if (st.status_str === 'error') { result = { error: 'workflow error', entry }; break; }
  }
  await new Promise(r => setTimeout(r, 3000));
}
if (!result) result = { error: 'timeout after 15min' };
return [{ json: { ...result, index, draft_dir: draftDir } }];

const fs = require('fs');
const path = require('path');
const all = $input.all();
const draftDir = all[0].json.draft_dir;
const files = fs.readdirSync(draftDir);
const images = files.filter(f => f.startsWith('img-')).sort();
const mdPath = path.join(draftDir, 'note.md');
let md = fs.readFileSync(mdPath, 'utf8');
md += '\n\n---\n\n## 图片\n\n' + images.map(f => `![${f}](${f})`).join('\n\n');
fs.writeFileSync(mdPath, md);

return [{ json: {
  draft_dir: draftDir,
  md_path: mdPath,
  images_count: images.length,
  images: images,
  hint: `SSH mini: ls ${draftDir}`
}}];
